 "content": "from collections import Counter


def transform(grid):
    """Fill axis-aligned intervals between matching marker cells with color 3."""
    out = [row[:] for row in grid]
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    markers = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row)
               if value != background]
    for i, (r1, c1) in enumerate(markers):
        for r2, c2 in markers[i + 1:]:
            if grid[r1][c1] != grid[r2][c2]:
                continue
            if r1 == r2:
                for c in range(min(c1, c2) + 1, max(c1, c2)):
                    if grid[r1][c] == background:
                        out[r1][c] = 3
            elif c1 == c2:
                for r in range(min(r1, r2) + 1, max(r1, r2)):
                    if grid[r][c1] == background:
                        out[r][c1] = 3
    return out
